  ui_story_30870101_15_dialog_content = "Dangkal sekali.",
  ui_story_30870101_16_dialog_content = "Meski aku memang suka teater...",
  ui_story_30870101_17_dialog_content = "Tugas bangsawan bukanlah sekadar di dalam ruangan menikmati hiburan.",
  ui_story_30870101_18_dialog_content = "Jika bukan hanya duduk di rumah bangsawan, maka...",
