  ui_story_30870101_29_dialog_content = "Benar.",
  ui_story_30870101_30_dialog_content = "Tidak jauh dari Northland.",
  ui_story_30870101_31_dialog_content = "Leluhurku berjalan ke sana demi mengakhiri Eclipsite.",
  ui_story_30870101_32_option_content = "Rediesel Desert?",
  ui_story_30870101_33_dialog_content = "Tempat kamu bisa melihat salju di gurun!",
