  ui_story_30870101_38_dialog_content = "Lagi pula, ini adalah tugas seorang bangsawan.",
  ui_story_30870101_39_dialog_content = "Ketika mencapai kaki bukit, mereka menemukan desa yang telah direbut musuh.",
  ui_story_30870101_40_dialog_content = "Eclipsite telah menguasainya dan hampir mengubahnya menjadi sarang mereka.",
  ui_story_30870101_41_dialog_content = "Namun, secara mengejutkan, masih ada orang yang tinggal di desa itu.",
  ui_story_30870101_42_dialog_content = "Akan tetapi, di sana mereka dalam bahaya!",
  ui_story_30870101_43_dialog_content = "Benar. Saat Eclipsite merebut desa, mereka tidak punya pilihan selain kabur ke gudang bawah tanah.",
  ui_story_30870101_44_dialog_content = "Mereka bertahan, mengandalkan simpanan makanan dan air mereka, tidak berani mengeluarkan suara.",
  ui_story_30870101_45_dialog_content = "Barulah ketika pasukan leluhurku tiba, ada secercah harapan bagi mereka. Orang-orang malang itu mengambil risiko dengan mengirim utusan untuk meminta bantuan.",
  ui_story_30870101_46_dialog_content = "Namun, utusan pertama yang merangkak keluar dari ruang bawah tanah tercabik-cabik oleh Eclipsite yang berpatroli.",
  ui_story_30870101_47_dialog_content = "Mengerikan!",
  ui_story_30870101_48_dialog_content = "Sayang sekali leluhurku tidak bisa menyelamatkannya. Pada saat leluhurku menaiki kudanya, Eclipsite telah mencabik-cabik utusan itu.",
  ui_story_30870101_49_dialog_content = "Leluhurku pergi mendekatinya, tetapi yang dia temukan hanyalah lengan baju yang sobek.",
  ui_story_30870101_50_option_content = "Leluhurmu memang pemberani...",
  ui_story_30870101_51_dialog_content = "Namun, sebagai bangsawan, melihat rakyat biasa tewas di depan mata bukanlah hal yang bisa diterima.",
  ui_story_30870101_52_option_content = "Utusan itu berani mencoba.",
  ui_story_30870101_53_dialog_content = "Ya. Dia sendiri layak menjadi bangsawan. Sayang sekali...",
  ui_story_30870101_54_dialog_content = "Leluhurku tidak akan membiarkan pengorbanan orang ini sia-sia, jadi mereka bergerak menuju desa dan menumpas Eclipsite di sana hingga tak tersisa.",
  ui_story_30870101_55_dialog_content = "Tentu saja, kami mengalami kehilangan... Beberapa bangsawan gugur, dan leluhurku kehilangan satu tangan karena cara bertarung mereka yang tidak sempurna.",
  ui_story_30870101_56_dialog_content = "Namun, mereka berhasil menyelamatkan para penduduk desa yang tersisa, jadi setidaknya tujuan mereka tercapai.",
  ui_story_30870101_57_dialog_content = "Tunggu dulu. Kamu bersikap terlalu santai dengan sesuatu yang begitu heroik!",
  ui_story_30870101_58_dialog_content = "Mereka membayar harga yang mahal demi menyelamatkan desa itu.",
  ui_story_30870101_59_dialog_content = "Heroik? Itu hanyalah tugas bangsawan.",
  ui_story_30870101_60_dialog_content = "Dan itulah arti dari bangsawan sejati.",
  ui_story_30870101_61_dialog_content = "Tidak lebih.",
  ui_story_30870101_62_dialog_content = "Makin santai kamu menyikapinya... makin aku merasa kagum...",
  ui_story_30870101_63_dialog_content = "Penduduk desa pasti sangat berterima kasih.",
  ui_story_30870101_64_dialog_content = "Benar. Untuk berterima kasih kepada leluhurku, mereka mengeluarkan semua makanan dan air yang mereka simpan dan membagikannya kepada leluhurku dan pasukannya.",
  ui_story_30870101_65_dialog_content = "Aku yakin tidak ada makanan yang tersisa ketika mereka selesai bertempur! Setelah pertempuran seperti itu, mereka pasti kelaparan.",
  ui_story_30870101_66_dialog_content = "Bukan... itu yang terjadi.",
  ui_story_30870101_67_dialog_content = "Leluhurku menolak makanan itu karena seorang bangsawan tidaklah pantas menerimanya.",
  ui_story_30870101_68_dialog_content = "Itu bagian dari menjadi bangsawan juga?",
  ui_story_30870101_69_option_content = "Jadi, menjadi bangsawan berarti melakukan mogok makan juga?",
  ui_story_30870101_70_dialog_content = "Kesulitan akan menempa mental seorang bangsawan, tapi bukan itu sebabnya.",
  ui_story_30870101_71_option_content = "Menjadi bangsawan berarti tidak mengambil keuntungan dari orang lain?",
  ui_story_30870101_72_dialog_content = "Tidak tamak mengejar kekayaan orang lain adalah bagian dari kode etik bangsawan, tetapi kali ini tidak demikian.",
  ui_story_30870101_73_dialog_content = "Leluhurku menolaknya karena makanan mereka kotor.",
  ui_story_30870101_74_dialog_content = "Bangsawan tidak boleh menyentuhnya.",
  ui_story_30870101_75_dialog_content = "Oh, baiklah, aku paham itu. Lagi pula, makanannya sudah lama berada di ruang bawah tanah, mungkin sudah basi dan berjamur.",
  ui_story_30870101_76_dialog_content = "Kamu bisa memakannya jika hanya itu yang kamu miliki, tetapi karena Eclipsite kini sudah mati, sepertinya itu tidak perlu.",
  ui_story_30870101_77_dialog_content = "Tidak, kamu salah paham.",
  ui_story_30870101_78_dialog_content = "Meski mereka membawakan kami makanan segar yang baru saja dimasak atau dibawa dari ladang...",
  ui_story_30870101_79_dialog_content = "Itu masih dianggap kotor.",
  ui_story_30870101_80_dialog_content = "Karena mereka semua rakyat biasa, dan semua makanan dari rakyat biasa itu kotor.",
  ui_story_30870101_81_dialog_content = "Seorang bangsawan tidak bisa memakan makanan kotor seperti itu.",
  ui_story_30870101_82_dialog_content = "Aku... benar-benar tidak paham.",
  ui_story_30870101_83_dialog_content = "Makanan itu berakhir di tempat yang sama. Apa bedanya?",
  ui_story_30870101_84_dialog_content = "Bagaimanapun, itu adalah biji-bijian yang disimpan di gudang bawah tanah untuk keadaan darurat.",
  ui_story_30870101_85_dialog_content = "Memberi leluhurmu makanan yang mereka butuhkan untuk bertahan hidup adalah ungkapan rasa terima kasih yang luar biasa.",
  ui_story_30870101_86_dialog_content = "Kamu harus menerimanya dengan senyuman, apa pun alasanmu. Kamu tidak boleh menolak kebaikan seperti itu!",
  ui_story_30870101_87_dialog_content = "Meski kamu tidak mau memakannya, jangan bilang kepada mereka bahwa makanannya kotor... Itu menghina!",
  ui_story_30870101_88_dialog_content = "Benarkah?",
  ui_story_30870101_89_dialog_content = "Kamu ada benarnya.",
  ui_story_30870101_90_dialog_content = "Itu satu-satunya makanan mereka yang tersisa...",
  ui_story_30870101_91_dialog_content = "Menawarkannya sebagai rasa terima kasih adalah ungkapan syukur yang tulus.",
  ui_story_30870101_92_dialog_content = "Itu yang kumaksud!",
  ui_story_30870101_93_dialog_content = "Baiklah, aku meminta maaf atas penolakan leluhurku pada waktu itu.",
  ui_story_30870101_94_dialog_content = "Dia sungguh tidak pengertian.",
  ui_story_30870101_95_dialog_content = "Makanan rakyat biasa mungkin kotor, tetapi seorang bangsawan tidak boleh melukai perasaan mereka.",
  ui_story_30870101_96_dialog_content = "Setidaknya dia harus menerimanya dan mencicipinya.",
  ui_story_30870101_97_dialog_content = "Lalu tunggu hingga meninggalkan desa itu untuk meludahkannya.",
  ui_story_30870101_98_dialog_content = "Tunggu... Itu masih terdengar janggal...",
  ui_story_30870101_99_dialog_content = "Masih?",
  ui_story_30870101_100_dialog_content = "Bukankah meludahkannya itu terasa sedikit aneh?",
  ui_story_30870101_101_dialog_content = "Jangan coba meyakinkanku lebih jauh. Itu adalah pengakuan terbesar yang bisa dilakukan oleh leluhurku, atau aku dalam hal ini.",
  ui_story_30870101_102_dialog_content = "Lagi pula, rakyat biasa dan bangsawan adalah makhluk yang benar-benar berbeda.",
  ui_story_30870101_103_dialog_content = "Sebagai bangsawan, kami harus melindungi rakyat biasa. Itulah tugas kami.",
  ui_story_30870101_104_dialog_content = "Sementara rakyat biasa, yang lemah dan tak berdaya, memerlukan perlindungan kami. Namun, mereka tetaplah kotor dan kumuh...",
  ui_story_30870101_105_dialog_content = "Begitulah keadaannya.",
  ui_story_30870101_106_dialog_content = "Namun, sementara untuk makanan itu... Leluhurku salah menilai.",
  ui_story_30870101_107_dialog_content = "Jika aku menghadapi situasi yang sama, dengan senang hati aku akan menerima makanannya.",
  ui_story_30870101_108_dialog_content = "Lalu meludahkannya di tempat mereka tidak akan melihatmu?",
  ui_story_30870101_109_dialog_content = "Ya.",
  ui_story_30870101_110_dialog_content = "Baiklah... Sepertinya begitulah yang paling bisa aku harapkan darimu.",
  ui_story_30870101_111_dialog_content = "Namun, bagaimana dengan tradisi tidak menyia-nyiakan makanan... Mungkin kamu tidak perlu meludahkannya?",
  ui_story_30870101_112_dialog_content = "Yah... bangsawan seharusnya tidak menyia-nyiakan makanan juga...",
  ui_story_30870101_113_dialog_content = "Lalu, bagaimana jika makanannya ternyata lezat?",
  ui_story_30870101_114_dialog_content = "Baiklah... Jika memang demikian... Tunggu dulu...",
  ui_story_30870101_115_dialog_content = "Haha, hanya bercanda.",
  ui_story_30870601_1_dialog_content = "Berterima kasihlah, PlayerName.",
  ui_story_30870601_2_dialog_content = "Aku mengutus seseorang untuk mengantarkan makanan laut premium yang ditangkap di teritori keluargaku ke Colossus.",
  ui_story_30870601_4_dialog_content = "Oh? Kenapa tiba-tiba?",
  ui_story_30870601_5_dialog_content = "Sebagaimana layaknya bangsawan menerima persembahan dan pujian dari rakyat biasa, mereka juga harus memberikan hal yang sama sebagai gantinya.",
  ui_story_30870601_6_dialog_content = "Bukankah harusnya seperti itu?",
  ui_story_30870601_7_dialog_content = "Baiklah. Terima kasih.",
  ui_story_30870601_8_dialog_content = "Sepertinya sekarang kau bisa menerima hadiah dari rakyat biasa dengan tangan terbuka.",
  ui_story_30870601_9_dialog_content = "Bukan hadiah, tapi persembahan.",
  ui_story_30870601_10_dialog_content = "Mereka mengambil hadiah yang paling murni dari laut, disertai dengan limpahan rasa hormat tertinggi...",
  ui_story_30870601_11_dialog_content = "Lalu mempersembahkannya kepada City Benefactor yang melindungi mereka. Itu adalah ritual suci.",
  ui_story_30870601_14_dialog_content = "Oh... Begitu, ya.",
  ui_story_30870601_15_dialog_content = "Teritori keluargamu itu tempat macam apa? Kau sering pergi ke sana?",
  ui_story_30870601_16_dialog_content = "Iskut mempunyai pulau yang sangat kaya sumber daya.",
  ui_story_30870601_16X1_dialog_content = "Tapi pulau itu terletak sangat jauh dari Lumopolis, jadi aku tak pernah ke sana. Aku juga tak tahu banyak tentang pulau itu.",
  ui_story_30870601_17_dialog_content = "Apa? Tak pernah?",
  ui_story_30870601_22_dialog_content = "Sepertinya aku akan mengunjunginya suatu saat nanti.",
  ui_story_30870601_23_dialog_content = "Kau juga mau?",
  ui_story_30870601_24_dialog_content = "Tentu! Aku suka pantai. Saat aku masih—",
  ui_story_30870601_25_dialog_content = "Kalau begitu, ayo ke sana sekarang. Aku mau meninjau pulau kami.",
  ui_story_30870601_26_dialog_content = "Aku akan mengganti biaya perjalanan Colossus ke sana, tenang saja.",
  ui_story_30870601_27_dialog_content = "Navigator Colossus, PlayerName, siap melayani!",
  ui_story_30870601_28_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_30870601_29_dialog_content = "Teritori milik keluarga Iskut benar-benar menenangkan, tanahnya juga subur.",
  ui_story_30870601_30_dialog_content = "Mataharinya, pantainya, dan ombaknya!",
  ui_story_30870601_31_dialog_content = "Aku kembali! Musim panas yang seru!",
  ui_story_30870601_32_dialog_content = "Tidak mendengarkan orang yang sedang bicara itu tidak sopan, tahu. Kenapa kau bersemangat sekali?",
  ui_story_30870601_33_dialog_content = "Ahem. Maaf. Aku senang karena akhirnya aku bisa menikmati keindahan laut.",
  ui_story_30870601_34_dialog_content = "Kau bilang apa tadi? Orang-orang bahagia tinggal di teritori keluargamu?",
  ui_story_30870601_35_dialog_content = "Kalau memang iya, jangan tegang begitu.",
  ui_story_30870601_36_dialog_content = "Kita kan sedang di pantai, kenapa tidak bersenang-senang?",
  ui_story_30870601_37_dialog_content = "Ngomong-ngomong soal pantai... kau kegerahan?",
  ui_story_30870601_38_dialog_content = "Aku harus ganti baju, nih?",
  ui_story_30870601_39_dialog_content = "Ya, tidak juga, sih... Cuma bertanya...",
  ui_story_30870601_40_dialog_content = "Aku membawa setelan renang, sih. Tapi bukan berarti harus kupakai, 'kan?",
  ui_story_30870601_41_option_content = "Sayang sekali.",
  ui_story_30870601_43_dialog_content = "Jadi, kau membawa setelan renang, tapi tak ingin memakainya?",
  ui_story_30870601_45_dialog_content = "Kok kau jadi kecewa begitu saat tahu aku tak ingin memakai setelan renangku?",
  ui_story_30870601_47_dialog_content = "Kau serius banget, sih. Santai saja, kita kan sedang di pantai...",
  ui_story_30870601_47X1_dialog_content = "Jadi, kukira kau akan memakai pakaian baru yang cocok untuk melakukan kegiatan musim panas di pantai.",
  ui_story_30870601_47X2_dialog_content = "Itu cuma dugaanku saja, sih.",
  ui_story_30870601_48_dialog_content = "Aku juga mempertimbangkan itu sewaktu berkemas, sih. Kalau kau juga berpikir begitu, akan kupakai setelan renangnya.",
  ui_story_30870601_49_dialog_content = "\"Setelan?\"",
  ui_story_30870601_50_option_content = "Kau benar.",
  ui_story_30870601_51_dialog_content = "Aku penasaran seperti apa rupanya.",
  ui_story_30870601_52_dialog_content = "Tentu saja elegan dan cocok untuk liburan.",
  ui_story_30870601_53_dialog_content = "Hmm, aku masih tak bisa membayangkannya.",
  ui_story_30870601_53X1_dialog_content = "Kalau kau memang sepenasaran itu, aku bisa memakai setelan itu untukmu.",
  ui_story_30870601_54_dialog_content = "Nanti kau bisa lihat sendiri.",
  ui_story_30870601_55_dialog_content = "Maksudmu…",
  ui_story_30870601_56_dialog_content = "Kau tak mau berkeliling dulu? Aman, kok. Pantai ini dijaga ketat oleh pengawal pribadiku.",
  ui_story_30870601_57_dialog_content = "Aku harus berangkat. Nanti aku segera kembali.",
  ui_story_30870601_58_dialog_content = "Oke, kutunggu di sini, ya.",
  ui_story_30870601_59_dialog_content = "<color=#e8d9bb>*suara deburan ombak*</color>",
  ui_story_30870601_60_dialog_content = "Menikmati angin sepoi-sepoi di pantai seorang diri tanpa perlu mengkhawatirkan apa-apa, syahdu sekali.",
  ui_story_30870601_61_dialog_content = "Waaaaaaaaaaah!",
  ui_story_30870601_62_dialog_content = "Suara apa itu?!",
  ui_story_30870601_63_dialog_content = "Diamlah! Kenapa kau menangis? Di mana ayahmu?",
  ui_story_30870601_64_dialog_content = "Kau tak bisa dengar, ya?!",
  ui_story_30870601_65_dialog_content = "A-aku kan sudah bilang! Ayahku ada di kapal, sedang melaut.",
  ui_story_30870601_66_dialog_content = "Aku tahu kau berbohong. Badai akan datang, nelayan mana yang tak tahu itu?",
  ui_story_30870601_67_dialog_content = "Tapi... tapi aku tak bohong!",
  ui_story_30870601_68_dialog_content = "Cukup. Suruh ayahmu untuk keluar dan membayar pajaknya. Kalau tidak, kaulah yang akan kami bawa.",
  ui_story_30870601_69_dialog_content = "Tapi kami sudah membayar pajak! Jumlahnya juga tidak sedikit...",
  ui_story_30870601_70_dialog_content = "Kalian cuma membayar nominal yang harus kalian bayar beserta nominal yang kalian pinjam.",
  ui_story_30870601_71_dialog_content = "Tapi, kalian belum membayar persembahan untuk Benefactor!",
  ui_story_30870601_72_dialog_content = "Benefactor? Apa kalian membicarakan tentang...",
  ui_story_30870601_73_dialog_content = "Siapa kau? Kenapa kau menguping?!",
  ui_story_30870601_74_dialog_content = "Aku cuma ingin tahu apa yang akan kalian lakukan pada bocah itu. Aku akan bertindak kalau kalian kelewat batas.",
  ui_story_30870601_75_dialog_content = "Apa Benefactor kalian ini butuh banyak persembahan?",
  ui_story_30870601_76_dialog_content = "Beraninya kau menghina Benefactor kami!",
  ui_story_30870601_77_dialog_content = "Apa? Aku bahkan tidak... Tolong aku!",
  ui_story_30870601_78_dialog_content = "<color=#e8d9bb>*gemuruh guntur*</color>",
  ui_story_30870601_79_dialog_content = "Itu petir?!",
  ui_story_30870601_81_dialog_content = "Whaaaa!",
  ui_story_30870601_82_dialog_content = "Ada yang datang dari laut! Mungkinkah dia...",
  ui_story_30870601_83_dialog_content = "<color=#e8d9bb>*ombak memecah*</color>",
  ui_story_30870601_84_dialog_content = "Konon, hanya ada satu orang yang bisa berjalan di atas ombak sementara petir menyambar-nyambar di angkasa...",
  ui_story_30870601_85_dialog_content = "Itu Beverly dalam balutan setelan renangnya...",
  ui_story_30870601_86_dialog_content = "<size=45>Dia Spirit of the Sea!</size>",
  ui_story_30870601_87_dialog_content = "Hah???",
  ui_story_30870601_88_dialog_content = "Ternyata benar! Lautan mengawasi kita selama ini!",
  ui_story_30870601_88X1_dialog_content = "Saat penjahat melakukan hal yang tak patut, lautan menghukum mereka.",
  ui_story_30870601_89_dialog_content = "Lautan mengutus seseorang yang terbalut zirah dan kepalanya berhiaskan mahkota hitam untuk menghukum orang jahat!",
  ui_story_30870601_90_dialog_content = "Utusan? Itukah aku?",
  ui_story_30870601_91_dialog_content = "Tolong kami, Utusan Laut!",
  ui_story_30870601_92_dialog_content = "Sepertinya kau ingin menceritakan semua masalahmu ke laut.",
  ui_story_30870601_93_dialog_content = "Kalau begitu, biarlah aku menjadi perantara pesanmu. Ceritakan semuanya.",
  ui_story_30870601_94_dialog_content = "Kalau ceritamu benar, aku akan membantumu.",
  ui_story_30870601_95_dialog_content = "Bagaimanapun juga, aku bertanggung jawab atas kehidupan kalian.",
  ui_story_30870601_96_dialog_content = "Menusuk sekali! Siapa yang peduli?!",
  ui_story_30870601_97_dialog_content = "Beraninya kalian bertindak tak sopan seperti itu!",
  ui_story_30870601_98_dialog_content = "Kalau aku tak menahan diri, kalian pasti sudah meregang nyawa.",
  ui_story_30870601_99_dialog_content = "Kalau kalian masih ingin bertarung, bersiap-siaplah menjemput ajal.",
  ui_story_30870601_100_dialog_content = "Hah?! Tidak, kita tak bisa melawannya. Kita butuh bantuan!",
  ui_story_30870601_101_dialog_content = "Tunggu saja!",
  ui_story_30870601_102_dialog_content = "Tunggu? Kalian menyuruhku untuk menunggu?",
  ui_story_30870601_103_dialog_content = "Nak, siapa mereka? Mereka mau apa darimu?",
  ui_story_30870601_104_dialog_content = "Mereka adalah pasukan pribadi Benefactor.",
  ui_story_30870601_105_dialog_content = "Mereka selalu bilang kalau mereka menjaga desa. Faktanya, mereka malah memeras semua orang.",
  ui_story_30870601_106_dialog_content = "Kapal kami rusak. Itulah sebabnya kami tak bisa memberikan persembahan makanan laut kepada Benefactor tahun ini.",
  ui_story_30870601_107_dialog_content = "Mereka meminjamkan kapal untuk ayahku, tapi mereka membebankan biaya berkali-kali lipat.",
  ui_story_30870601_108_dialog_content = "Mereka juga memukulku dan memaksaku melakukan pekerjaan kasar...",
  ui_story_30870601_108X1_dialog_content = "Akhirnya, kami berhasil membayar pajak dan biaya sewa kapal, tapi mereka kembali dan menagih persembahan untuk Benefactor.",
  ui_story_30870601_109_dialog_content = "Katanya, mereka akan merampas barang-barang di rumah kalau kami tak memberikan persembahan apa-apa.",
  ui_story_30870601_110_dialog_content = "Kami tak punya banyak barang di rumah, jadi ayahku pergi melaut...",
  ui_story_30870601_111_dialog_content = "Tunggu, Nak.",
  ui_story_30870601_112_dialog_content = "Aku akan mengambilkan sesuatu untukmu dari Colossus. Ada hal lain yang mengusik pikiranmu?",
  ui_story_30870601_113_dialog_content = "Colossus? Apa itu? Itu istanamu?",
  ui_story_30870601_114_dialog_content = "Bukan, Colossus lebih jadul dan tak semegah istana.",
  ui_story_30870601_115_dialog_content = "Ayo, PlayerName, ayo kembali ke Colossus.",
  ui_story_30870601_116_dialog_content = "Apa yang mau kaulakukan terkait area ini? Benefactor di sini pasti...",
  ui_story_30870601_117_dialog_content = "Bukan, koordinatnya pasti salah. Kita harus kembali dan mengecek ulang.",
  ui_story_30870601_118_dialog_content = "Tadi aku berkeliling sejenak. Sejauh mata memandang, semuanya tampak tua dan terbengkalai, sangat berbeda dari wilayah milik keluargaku.",
  ui_story_30870601_119_dialog_content = "Tapi tentu saja, ada kemungkinan lain...",
  ui_story_30870601_120_dialog_content = "Kau yang berambut pirang! Berhenti lalu berbalik!",
  ui_story_30870601_121_dialog_content = "Kau nekat sekali, ya? Beraninya kau membuat masalah di wilayah Iskut!",
  ui_story_30870601_123_dialog_content = "Aku tak pernah menyangka nama keluargaku diucapkan dengan nada seperti itu.",
  ui_story_30870601_124_dialog_content = "Aku mengecewakan leluhurku.",
  ui_story_30870601_125_dialog_content = "Kau bicara apa? Cepat berbalik dan beri tahukan...",
  ui_story_30870601_126_dialog_content = "Oke, akan kuberitahukan namaku. Itu memang tugasku.",
  ui_story_30870601_127_dialog_content = "Wajah ini... Kau... Kau pasti...",
  ui_story_30870601_128_dialog_content = "Aku Beverly Iskut. Belum lama ini aku mewarisi takhta sebagai Duchess, tapi...",
  ui_story_30870601_129_dialog_content = "L-Lady Iskut?! Maaf saya tak mengenal Anda! Tolong maafkan saya!",
  ui_story_30870601_130_dialog_content = "Kau membuat laporan keuangan palsu, kau memungut pajak dari orang tanpa izinku, kau membolehkan bawahanmu merampok warga sipil, dan kau memotong pembicaraanku.",
  ui_story_30870601_131_dialog_content = "Dan kau meminta maaf?",
  ui_story_30870601_132_dialog_content = "Saya benar-benar minta maaf, Lady. Saya...",
  ui_story_30870601_133_dialog_content = "Cukup. Tak semua masalah harus diselesaikan di sini.",
  ui_story_30870601_134_dialog_content = "Bawa ini ke bocah yang menunggu di ujung timur pantai. Jangan beri tahukan dia siapa aku sebenarnya.",
  ui_story_30870601_135_dialog_content = "Lalu hubungi pasukan pribadi dan tunggu perintahku.",
  ui_story_30870601_136_dialog_content = "Y-Ya...",
  ui_story_30870601_137_dialog_content = "<color=#e8d9bb>Beberapa waktu kemudian...</color>",
  ui_story_30870601_138_dialog_content = "PlayerName, kau sedang senggang, 'kan?",
  ui_story_30870601_139_dialog_content = "Antarkan aku ke koordinat ini, ya. Kau boleh ikut denganku, kok.",
  ui_story_30870601_140_dialog_content = "Bukankah ini wilayahmu?",
  ui_story_30870601_141_dialog_content = "Kurasa aku harus menjelaskan sesuatu kepada semuanya. Ayo.",
  ui_story_30870601_142_dialog_content = "<color=#e8d9bb>*deburan ombak*</color>",
  ui_story_30870601_143_dialog_content = "Kalau semuanya sudah selesai, aku bisa mengajakmu berkeliling.",
  ui_story_30870601_144_dialog_content = "Anggap saja sebagai pengganti karena kau tak sempat menikmati keindahan pantai waktu itu.",
  ui_story_30870601_145_dialog_content = "Kau langsung mengenakan setelan renangmu kali ini.",
  ui_story_30870601_146_dialog_content = "Itu karena kita akan menemui bocah itu lagi.",
  ui_story_30870601_146X1_dialog_content = "Mungkin dia ingin bertemu dengan sang Utusan.",
  ui_story_30870601_147_dialog_content = "Nota Utusan! Kau kembali!",
  ui_story_30870601_148_dialog_content = "Desa berubah drastis sejak kedatanganmu terakhir kali.",
  ui_story_30870601_149_dialog_content = "Badai semakin jarang, ikan tangkapan semakin banyak, dan prajurit yang semena-mena sudah tak pernah datang lagi.",
  ui_story_30870601_150_dialog_content = "Bahkan ada yang bilang kalau Benefactor akan menurunkan pajak dan mengaspal jalan.",
  ui_story_30870601_151_dialog_content = "Sejumlah pedagang mampir ke kota. Bahkan salah satu dari mereka memberikan kapal baru untuk kami!",
  ui_story_30870601_152_dialog_content = "Lutut ayahku juga semakin membaik.",
  ui_story_30870601_153_dialog_content = "Kau hebat sekali, Nona Utusan!",
  ui_story_30870601_154_dialog_content = "Sebenarnya, ada yang ingin kusampaikan padamu.",
  ui_story_30870601_155_dialog_content = "Aku bukan Utusan Laut. Namaku Beverly Iskut.",
  ui_story_30870601_156_dialog_content = "Akulah Benefactor yang kau bicarakan itu.",
  ui_story_30870601_157_dialog_content = "... Benefactor?",
  ui_story_30870601_158_dialog_content = "Ya.",
  ui_story_30870601_159_dialog_content = "Tak mungkin! Kau mencoba menyembunyikan identitasmu, 'kan?",
  ui_story_30870601_160_dialog_content = "Konon, Utusan akan berubah menjadi manusia saat naik ke darat dan menyembunyikan identitasnya.",
  ui_story_30870601_160X1_dialog_content = "Kau pasti berpura-pura menjadi Benefactor.",
  ui_story_30870601_161_dialog_content = "Jangan khawatir, aku tak akan menceritakan penampilanmu kepada siapa-siapa.",
  ui_story_30870601_162_dialog_content = "Tolong, jaga tempat ini selamanya.",
  ui_story_30870601_163_dialog_content = "Baiklah, Nak.",
  ui_story_30870601_164_dialog_content = "Aku akan menjaga tempat ini selamanya karena itulah tugasku."
}
return config
